package com.saasquatch.intelligence.entity;
import jakarta.persistence.*; import java.util.*; import com.fasterxml.jackson.annotation.JsonIgnore;
@Entity @Table(name="companies") public class Company { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; private String domain; private String industry; private Integer employeeCount; private Double estimatedRevenueMillions; private Double growthRate; private String technologyStack; private boolean verified=true; @JsonIgnore @OneToMany(mappedBy="company") private List<Lead> leads=new ArrayList<>(); public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getDomain(){return domain;} public void setDomain(String v){domain=v;} public String getIndustry(){return industry;} public void setIndustry(String v){industry=v;} public Integer getEmployeeCount(){return employeeCount;} public void setEmployeeCount(Integer v){employeeCount=v;} public Double getEstimatedRevenueMillions(){return estimatedRevenueMillions;} public void setEstimatedRevenueMillions(Double v){estimatedRevenueMillions=v;} public Double getGrowthRate(){return growthRate;} public void setGrowthRate(Double v){growthRate=v;} public String getTechnologyStack(){return technologyStack;} public void setTechnologyStack(String v){technologyStack=v;} public boolean isVerified(){return verified;} public void setVerified(boolean v){verified=v;} }